<?php require 'config.php'; if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');if($name!==''){$pdo->prepare("INSERT INTO parents(name,phone,email) VALUES(?,?,?)")->execute([$name,$phone,$email]);header('Location:index.php#parents');exit;}} ?><!DOCTYPE html><html><head><meta charset="UTF-8"><link rel="stylesheet" href="assets/style.css"><title>Add parent | CareTrack</title></head><body><main class="form-page"><a href="index.php">← Dashboard</a><section class="panel"><h1>Add parent / guardian</h1><form method="post"><label>Full name<input name="name" required></label><label>Phone<input name="phone" type="tel"></label><label>Email<input name="email" type="email"></label><button class="button">Save parent</button></form></section></main></body></html>